import base64,gzip,json,sqlite3
DATA=""
rows=json.loads(gzip.decompress(base64.b64decode(DATA)))
db="/opt/lzh/v7re/data/model/v7_model.sqlite"
c=sqlite3.connect(db)
c.execute("DROP TABLE IF EXISTS imux_codes")
c.execute("""CREATE TABLE imux_codes (tile_type TEXT, mux TEXT, lut_input INTEGER, src_wire TEXT, row INTEGER, row_word INTEGER, col_code TEXT, col_index INTEGER, idx INTEGER, field_bit INTEGER, source TEXT, PRIMARY KEY(tile_type,mux,src_wire))""")
c.executemany("INSERT INTO imux_codes VALUES (?,?,?,?,?,?,?,?,?,?,?)",[(r["tile_type"],r["mux"],r["lut_input"],r["src_wire"],r["row"],r["row_word"],r["col_code"],r["col_index"],r["index"],r["field_bit"],"prjxray_a7_20261025") for r in rows])
c.commit()
print("remote imux_codes", c.execute("select count(*) from imux_codes").fetchone()[0])
print(c.execute("select * from imux_codes where mux='IMUX_L8' order by idx limit 3").fetchall())
